variable "node_role_arn" {
  type = string
}

variable "private_subnet_ids" {
  type = list(string)
}

resource "aws_cloudwatch_event_rule" "nightly" {
  name        = "nightly-etl"
  description = "Trigger the ETL Lambda every night"

  schedule_expression = "cron(0 3 * * ? *)"
}

resource "aws_cloudwatch_event_target" "etl" {
  rule      = aws_cloudwatch_event_rule.nightly.name
  target_id = "etl-lambda"
  arn       = aws_lambda_function.etl.arn
}

resource "aws_lambda_permission" "events" {
  statement_id  = "AllowEventBridge"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.etl.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.nightly.arn
}

resource "aws_lambda_function" "etl" {
  function_name = "nightly-etl"
  filename      = "etl.zip"
  role          = var.lambda_role_arn
  handler       = "etl.handler"
  runtime       = "python3.12"
}

